import sys as _sys

# FLAG OS — harus didefinisikan SEBELUM _get_app_dir() dan blok font.
# PENTING: taruh di top-level module scope (bukan di dalam/di bawah fungsi
# lain) supaya PyInstaller optimizer tidak memotongnya saat membuat bundle.
_IS_MAC = _sys.platform == "darwin"
_IS_WIN = _sys.platform == "win32"

def _exe_name(base):
    """Tambah .exe hanya di Windows; di Mac/Linux nama tetap 'ffmpeg'."""
    return base + ".exe" if _IS_WIN else base

def _get_bundle_dir():
    """Return folder temp PyInstaller saat berjalan sebagai EXE."""
    if getattr(_sys, "frozen", False) and hasattr(_sys, "_MEIPASS"):
        return Path(_sys._MEIPASS)
    return Path(__file__).parent

BUNDLE_DIR = _get_bundle_dir()

def _get_app_dir():
    """Folder PERMANEN untuk menyimpan settings.json (beda dari BUNDLE_DIR).
    BUNDLE_DIR (_MEIPASS) adalah folder temp yang dihapus & dibuat ulang setiap
    EXE/app dijalankan, jadi tidak boleh dipakai untuk menyimpan data yang
    harus bertahan antar sesi (settings, ffmpeg path, tema, dll).
    - Sebagai .py         : folder script ini.
    - Sebagai .exe        : folder tempat file .exe itu sendiri berada.
    - Sebagai .app (macOS): ~/Library/Application Support/CREATUBE STUDIO
                            ( Contents/MacOS di dalam bundle TIDAK permanen
                              & read-only saat signed/notarized ).
    """
    if getattr(_sys, "frozen", False):
        if _IS_MAC:
            support = Path.home() / "Library" / "Application Support" / "CREATUBE STUDIO"
            support.mkdir(parents=True, exist_ok=True)
            return support
        return Path(_sys.executable).resolve().parent
    return Path(__file__).resolve().parent

APP_DIR = _get_app_dir()

