def _set_theme_globals(mode):
    """Update konstanta warna global sesuai mode ('light'/'dark').
    Dipanggil sebelum UI dibangun (startup) maupun saat toggle runtime."""
    global BG, SURFACE, SURF2, SURF3, ACCENT, TEAL, SUCCESS, WARN, DANGER
    global PURPLE, GOLD, PINK, CYAN, TEXT, MUTED, CARD_BORDER, LOG_BG
    t = THEMES.get(mode, THEMES["light"])
    BG, SURFACE, SURF2, SURF3 = t["BG"], t["SURFACE"], t["SURF2"], t["SURF3"]
    ACCENT, TEAL, SUCCESS, WARN, DANGER = t["ACCENT"], t["TEAL"], t["SUCCESS"], t["WARN"], t["DANGER"]
    PURPLE, GOLD, PINK, CYAN = t["PURPLE"], t["GOLD"], t["PINK"], t["CYAN"]
    TEXT, MUTED, CARD_BORDER, LOG_BG = t["TEXT"], t["MUTED"], t["CARD_BORDER"], t["LOG_BG"]

