def _mac_path_dirs():
    """Folder-folder tempat ffmpeg/ffprobe biasanya terinstall di macOS
    (Homebrew Intel, Apple Silicon, MacPorts, dan bundle di dalam .app)."""
    out = []
    seen = set()
    for d in [
        "/usr/local/bin",                      # Homebrew (Intel)
        "/opt/homebrew/bin",                   # Homebrew (Apple Silicon)
        "/opt/local/bin",                      # MacPorts
        "/usr/bin",
    ]:
        if d not in seen:
            seen.add(d)
            out.append(d)
    # Di dalam .app bundle (PyInstaller --windowed): Contents/MacOS, Contents/Resources
    for b in (BUNDLE_DIR, _get_app_dir()):
        for sub in ("", "ffmpeg/bin", "bin"):
            p = (b / sub).resolve() if sub else b.resolve()
            if str(p) not in seen:
                seen.add(str(p))
                out.append(str(p))
    return out

def _find_ffmpeg_candidates():
    """Cari FFmpeg: bundled dulu, lalu PATH sistem + lokasi khas tiap OS
    (Windows: C:\\ffmpeg, Program Files, WinGet | Mac: /opt/homebrew,
    /usr/local/bin, MacPorts | Linux: /usr/bin, /snap)."""
    cands = []
    seen = set()

    def _add(p):
        if p and str(p) not in seen:
            seen.add(str(p))
            cands.append(str(p))

    # 1) Di dalam folder aplikasi (python .py atau bundle PyInstaller)
    for base in (BUNDLE_DIR, Path(__file__).resolve().parent):
        for sub in ("ffmpeg/bin", "ffmpeg", "bin"):
            _add(base / sub / _exe_name("ffmpeg"))

    # 2) Variabel PATH yang diatur user (paling sering dipakai)
    for p in os.environ.get("PATH", "").split(os.pathsep):
        _add(Path(p) / _exe_name("ffmpeg"))

    # 3) Command biasa — berfungsi kalau PATH sistem terbaca (kondisi normal)
    _add(shutil.which("ffmpeg") or "")
    _add(_exe_name("ffmpeg"))

    home = Path.home()

    if _IS_WIN:
        cands += [
            r"C:\ffmpeg\bin\ffmpeg.exe",
            r"C:\ffmpeg\ffmpeg.exe",
            r"C:\Program Files\ffmpeg\bin\ffmpeg.exe",
            r"C:\Program Files (x86)\ffmpeg\bin\ffmpeg.exe",
        ]
        _add(home / "ffmpeg" / "bin" / "ffmpeg.exe")
        _add(home / "ffmpeg" / "ffmpeg.exe")

        la = os.environ.get("LOCALAPPDATA", "")
        if la:
            _add(Path(la) / "Microsoft" / "WinGet" / "Links" / "ffmpeg.exe")
            for p in glob.glob(str(Path(la) / "Microsoft" / "WinGet" / "Packages" / "Gyan*" / "**" / "ffmpeg.exe"), recursive=True):
                _add(p)

    elif _IS_MAC:
        # Aplikasi GUI di macOS DIPANGKAI dari Finder, jadi PATH-nya cuma
        # /usr/bin:/bin — folder Homebrew (/opt/homebrew/bin atau
        # /usr/local/bin) TIDAK terbaca. Itulah sebabnya kita cek manual.
        for d in _mac_path_dirs():
            _add(Path(d) / "ffmpeg")
        _add(home / "ffmpeg" / "bin" / "ffmpeg")
        _add(home / "ffmpeg" / "ffmpeg")
        # Path lama dari instalasi node/elektron atau user manual
        _add(home / ".local" / "bin" / "ffmpeg")
    else:
        # Linux
        for d in ("/usr/bin", "/usr/local/bin", "/snap/bin", "/opt/ffmpeg/bin"):
            _add(Path(d) / "ffmpeg")

    return cands

def test_ffmpeg(path):
    if not path:
        return False, ""
    try:
        flags = 0x08000000 if sys.platform == "win32" else 0
        r = subprocess.run(
            [path, "-version"],
            capture_output=True,
            text=True,
            timeout=8,
            creationflags=flags
        )
        if r.returncode == 0:
            ver = r.stdout.split("\n")[0]
            return True, ver
        return False, ""
    except Exception:
        return False, ""

def find_ffmpeg():
    for c in _find_ffmpeg_candidates():
        ok, _ = test_ffmpeg(c)
        if ok:
            return c
    return ""

def _ff_sibling(ffmpeg_path, sibling):
    """Cari ffprobe/ffplay di folder yang sama dengan ffmpeg yang dipakai.
    - Windows : /path/ffmpeg.exe -> /path/ffprobe.exe
    - Mac/Linux: /path/ffmpeg    -> /path/ffprobe
    Jika tidak ada, coba cari di lokasi instalasi standar OS."""
    if not ffmpeg_path:
        return ""
    p = Path(ffmpeg_path)
    # Kalau user menulis path tanpa ekstensi, tangani juga.
    direct = p.parent / (p.stem.replace("ffmpeg", sibling) + p.suffix)
    if direct.exists():
        return str(direct)
    cands = [str(p.parent / (sibling + p.suffix)),
             str(p.parent / sibling),
             str(p.parent / (sibling + ".exe"))]
    # Cari di folder instalasi standar
    if _IS_MAC:
        for d in _mac_path_dirs():
            cands.append(str(Path(d) / sibling))
    elif not _IS_WIN:
        for d in ("/usr/bin", "/usr/local/bin", "/snap/bin"):
            cands.append(str(Path(d) / sibling))
    for c in cands:
        if Path(c).exists():
            return c
    # Fallback: andalkan PATH (bisa jadi berbeda folder dengan ffmpeg)
    w = shutil.which(sibling)
    return w or ""

# ─── Buka file / folder (Windows · macOS · Linux) ─────────────────────────────

def open_file(path):
    """Buka file dengan aplikasi default OS (untuk preview & 'putar file')."""
    try:
        if _IS_WIN:
            os.startfile(str(path))            # pylint: disable=no-member
        elif _IS_MAC:
            subprocess.Popen(["open", str(path)])
        else:
            subprocess.Popen(["xdg-open", str(path)])
        return True
    except Exception:
        return False

def reveal_in_folder(path):
    """Tampilkan file/folder di file manager OS.
    - Windows : explorer /select,<file>
    - macOS   : open -R <file>   (reveal di Finder)
    - Linux   : buka folder induknya (compath thunar/dolphin/nautilus/xdg-open)"""
    p = Path(path)
    target = str(p.parent if p.is_file() else p)
    try:
        if _IS_WIN:
            subprocess.Popen(["explorer", f"/select,{p}"])
        elif _IS_MAC:
            subprocess.Popen(["open", "-R", str(p)])
        else:
            opened = False
            for fm in ("xdg-open", "nautilus", "dolphin", "thunar", "nemo", "pcmanfm"):
                if shutil.which(fm):
                    subprocess.Popen([fm, target])
                    opened = True
                    break
            if not opened:
                open_file(target)
        return True
    except Exception:
        # Fallback terakhir: buka foldernya saja
        return open_file(target)

def get_duration_ffmpeg(ffmpeg_path, filepath):
    try:
        flags = 0x08000000 if sys.platform == "win32" else 0
        r = subprocess.run(
            [ffmpeg_path, "-i", filepath],
            capture_output=True,
            text=True,
            timeout=15,
            encoding="utf-8",
            errors="replace",
            creationflags=flags
        )
        m = re.search(r"Duration:\s*(\d+):(\d+):(\d+\.?\d*)", r.stderr)
        if m:
            h, mi, s = int(m.group(1)), int(m.group(2)), float(m.group(3))
            return h * 3600 + mi * 60 + s
    except Exception:
        pass
    return 0.0

def get_video_info(ffmpeg_path, filepath):
    """Mendapatkan resolusi dan FPS video menggunakan ffprobe."""
    info = {"width": 0, "height": 0, "fps": 0}
    try:
        ffprobe = _ff_sibling(ffmpeg_path, "ffprobe")
        flags = 0x08000000 if sys.platform == "win32" else 0
        cmd = [ffprobe, "-v", "quiet", "-print_format", "json", "-show_streams", filepath]
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=15, creationflags=flags)
        if result.returncode == 0:
            data = json.loads(result.stdout)
            for stream in data.get("streams", []):
                if stream.get("codec_type") == "video":
                    info["width"] = stream.get("width", 0)
                    info["height"] = stream.get("height", 0)
                    fps_str = stream.get("r_frame_rate", "0/1")
                    if "/" in fps_str:
                        num, den = fps_str.split("/")
                        info["fps"] = round(float(num) / float(den), 2) if float(den) != 0 else 0
                    break
    except:
        pass
    return info

def run_ffmpeg_bg(cmd, on_progress=None, on_done=None, total_duration=None):
    def worker():
        try:
            flags = 0x08000000 if sys.platform == "win32" else 0
            proc = subprocess.Popen(
                cmd,
                stderr=subprocess.PIPE,
                stdout=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                creationflags=flags
            )
            dur_total = total_duration if (total_duration and total_duration > 0) else None
            stderr_buf = []
            for line in proc.stderr:
                stderr_buf.append(line)
                if dur_total is None and "Duration:" in line:
                    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+\.?\d*)", line)
                    if m:
                        h, mi, s = int(m.group(1)), int(m.group(2)), float(m.group(3))
                        dur_total = h * 3600 + mi * 60 + s
                if on_progress and dur_total and "time=" in line:
                    m = re.search(r"time=(\d+):(\d+):(\d+\.?\d*)", line)
                    if m:
                        h, mi, s = int(m.group(1)), int(m.group(2)), float(m.group(3))
                        pct = min((h * 3600 + mi * 60 + s) / dur_total, 1.0)
                        try:
                            on_progress(pct)
                        except:
                            pass
            proc.wait()
            _last_err = "".join(stderr_buf[-30:])
            ok = proc.returncode == 0
            if not ok:
                try:
                    dbg_err = str(Path.home() / "Videos" / "CreaTubeStudio" / "_last_ffmpeg_err.txt")
                    Path(dbg_err).parent.mkdir(parents=True, exist_ok=True)
                    open(dbg_err, "w", encoding="utf-8", errors="replace").write(_last_err)
                except:
                    pass
            if on_done:
                try:
                    on_done(ok, proc.returncode if ok else _last_err[-500:])
                except:
                    pass
        except Exception as e:
            if on_done:
                try:
                    on_done(False, str(e))
                except:
                    pass
    threading.Thread(target=worker, daemon=True).start()

def _tmp_path(name):
    """Path file kerja sementara (concat list, preview, dll) di folder temp
    sistem — BUKAN di folder output — supaya folder output user hanya berisi
    hasil render & file timestamp."""
    d = Path(tempfile.gettempdir()) / "CreatubeStudio_tmp"
    d.mkdir(parents=True, exist_ok=True)
    return str(d / name)

def secs_to_ts(s):
    if s < 0:
        s = 0
    return f"{int(s // 3600):02d}:{int((s % 3600) // 60):02d}:{int(s % 60):02d}"

