# ─── Widget helpers ───────────────────────────────────────────────────────────
def RoundedBtn(parent, text, cmd, bg=None, fg=None, hover_bg=None, radius=8, **kw):
    if bg is None: bg = SURF2
    if fg is None: fg = TEXT
    """Tombol rounded menggunakan Canvas untuk border radius yang sesungguhnya."""
    font = kw.pop("font", FN)
    padx = kw.pop("padx", 14)
    pady = kw.pop("pady", 7)
    width_px = kw.pop("width_px", None)
    hover = hover_bg or _darken(bg, 0.12)

    frame = tk.Frame(parent, bg=parent.cget("bg") if hasattr(parent, "cget") else BG)
    canvas = tk.Canvas(frame, bg=parent.cget("bg") if hasattr(parent, "cget") else BG,
                       highlightthickness=0, cursor="hand2")

    # Measure text size
    import tkinter.font as tkfont
    try:
        f = tkfont.Font(font=font)
        tw = f.measure(text)
        th = f.metrics("linespace")
    except:
        tw, th = 80, 16

    w = (width_px or tw) + padx * 2
    h = th + pady * 2

    canvas.config(width=w, height=h)
    canvas.pack()

    def _draw_rect(color):
        canvas.delete("all")
        r2 = min(radius, h//2)
        x0, y0, x1, y1 = 0, 0, w, h
        canvas.create_arc(x0, y0, x0+2*r2, y0+2*r2, start=90, extent=90, fill=color, outline=color)
        canvas.create_arc(x1-2*r2, y0, x1, y0+2*r2, start=0, extent=90, fill=color, outline=color)
        canvas.create_arc(x0, y1-2*r2, x0+2*r2, y1, start=180, extent=90, fill=color, outline=color)
        canvas.create_arc(x1-2*r2, y1-2*r2, x1, y1, start=270, extent=90, fill=color, outline=color)
        canvas.create_rectangle(x0+r2, y0, x1-r2, y1, fill=color, outline=color)
        canvas.create_rectangle(x0, y0+r2, x1, y1-r2, fill=color, outline=color)
        canvas.create_text(w//2, h//2, text=text, fill=fg, font=font, anchor="center")

    _draw_rect(bg)
    canvas.bind("<Enter>", lambda e: _draw_rect(hover))
    canvas.bind("<Leave>", lambda e: _draw_rect(bg))
    canvas.bind("<Button-1>", lambda e: cmd())
    canvas.bind("<ButtonRelease-1>", lambda e: _draw_rect(hover))
    return frame

def _darken(hex_color, amount=0.12):
    """Darken a hex color by amount (0-1)."""
    try:
        h = hex_color.lstrip("#")
        r, g, b = int(h[0:2],16), int(h[2:4],16), int(h[4:6],16)
        r = max(0, int(r * (1 - amount)))
        g = max(0, int(g * (1 - amount)))
        b = max(0, int(b * (1 - amount)))
        return f"#{r:02x}{g:02x}{b:02x}"
    except:
        return hex_color

def Btn(parent, text, cmd, color=None, fg=None, active_bg=None, **kw):
    if color is None: color = SURF2
    if fg is None: fg = TEXT
    font = kw.pop("font", FN)
    padx = kw.pop("padx", 12)
    pady = kw.pop("pady", 7)
    ab = kw.pop("activebackground", active_bg or _darken(color))
    b = tk.Button(parent,
                  text=text,
                  command=cmd,
                  bg=color,
                  fg=fg,
                  font=font,
                  relief="flat",
                  bd=0,
                  padx=padx,
                  pady=pady,
                  cursor="hand2",
                  activebackground=ab,
                  activeforeground=fg,
                  **kw)
    return b

