def Card(parent, title="", icon="", fg=None, **kw):
    if fg is None: fg = SURFACE
    kw.pop("bg", None)
    outer = tk.Frame(parent, bg=CARD_BORDER, padx=1, pady=1)
    f = tk.Frame(outer, bg=fg, relief="flat", **kw)
    f.pack(fill="both", expand=True)
    if title:
        title_fr = tk.Frame(f, bg=fg)
        title_fr.pack(fill="x", padx=10, pady=(9, 3))
        tk.Frame(title_fr, bg=ACCENT, width=3).pack(side="left", fill="y", padx=(0, 8))
        hdr_txt = f"{icon}  {title}" if icon else title
        tk.Label(title_fr, text=hdr_txt.upper(), bg=fg, fg=ACCENT, font=FCARD).pack(side="left")
    # Return outer so pack/grid works naturally
    outer._card_inner = f
    return outer

def LogBox(parent, h=5):
    fr = tk.Frame(parent, bg=SURF2, bd=1, relief="flat")
    sb = tk.Scrollbar(fr, bg=SURF2, troughcolor=BG, width=10)
    sb.pack(side="right", fill="y")
    t = tk.Text(fr,
                height=h,
                bg=LOG_BG,
                fg=TEXT,
                font=FMO,
                relief="flat",
                bd=6,
                yscrollcommand=sb.set,
                state="disabled",
                wrap="word",
                selectbackground=SURF3,
                selectforeground=TEXT)
    t.pack(side="left", fill="both", expand=True)
    sb.config(command=t.yview)
    return fr, t

def logw(t, msg):
    t.configure(state="normal")
    t.insert("end", msg + "\n")
    t.see("end")
    t.configure(state="disabled")

def PBar(parent):
    pb = ttk.Progressbar(parent, mode="determinate")
    return pb

def Scale(parent, **kw):
    bg = kw.pop("bg", SURF2)
    fg = kw.pop("fg", TEXT)
    return tk.Scale(parent,
                    bg=bg,
                    fg=fg,
                    troughcolor=SURF3,
                    highlightthickness=0,
                    activebackground=ACCENT,
                    **kw)

# ─── App ─────────────────────────────────────────────────────────────────────

class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("CREATUBE STUDIO")
        self._set_app_icon()
        self._center_window(1060, 680)
        self.resizable(False, False)
        # Font default. Harus berupa objek Font (bukan string "DejaVu Sans 10")
        # karena Tk memecah string dengan spasi: "DejaVu Sans 10" dianggap
        # family="DejaVu" size="Sans" -> error. Objek Font terdaftar sebagai
        # named font di Tcl, jadi aman untuk nama family yang mengandung spasi.
        try:
            import tkinter.font as _tkfont
            _df = _tkfont.Font(family=FONT_FAMILY, size=10)
            self.option_add("*Font", _df)
        except Exception:
            pass

        self.cfg = {
            "ffmpeg": "",
            "outdir": str(Path.home() / ("Movies" if _IS_MAC else "Videos") / "CreaTubeStudio"),
            "fmt": "mp4",
            "theme": "light",  # light, dark
        }
        self.metadata = {
            "title": "CREATUBE STUDIO Output",
            "author": "KelasYoutubeBarengMasTian",
            "copyright": "© 2026 KelasYoutubeBarengMasTian.com",
            "publisher": "CREATUBE STUDIO",
            "comment": "Created with CREATUBE STUDIO — KelasYoutubeBarengMasTian.com",
        }

        self._load_cfg()
        self._load_metadata()

        # Terapkan tema (light/dark) tersimpan SEBELUM widget dibuat, supaya
        # tidak perlu re-render ulang saat startup.
        _set_theme_globals(self.cfg.get("theme", "light"))
        self.configure(bg=BG)

        Path(self.cfg["outdir"]).mkdir(parents=True, exist_ok=True)
        setup_style()
        self._ui()

        # Deteksi/validasi FFmpeg dijalankan setelah window tampil, di background
        # thread, supaya tools langsung kebuka cepat tanpa menunggu subprocess.
        self.after(50, self._init_ffmpeg_async)

    def _init_ffmpeg_async(self):
        import queue
        q = queue.Queue()

        def worker():
            cached = self.cfg.get("ffmpeg", "")
            ok, _ = test_ffmpeg(cached) if cached else (False, "")
            if not ok:
                detected = find_ffmpeg()
                if detected:
                    self.cfg["ffmpeg"] = detected
                    self._save_cfg()
                    ok, _ = test_ffmpeg(detected)
            q.put(ok)

        threading.Thread(target=worker, daemon=True).start()

        def poll():
            try:
                ok = q.get_nowait()
            except Exception:
                self.after(80, poll)
                return
            try:
                self._update_ff_lbl(ok)
            except Exception:
                pass

        self.after(80, poll)

    def _center_window(self, w, h):
        """Pasang ukuran window tetap (w x h) dan posisikan tepat di tengah layar."""
        self.update_idletasks()
        sw = self.winfo_screenwidth()
        sh = self.winfo_screenheight()
        x = (sw - w) // 2
        y = (sh - h) // 2
        self.geometry(f"{w}x{h}+{x}+{y}")

    def _set_app_icon(self):
        """Pasang icon CREATUBE di title bar & taskbar window ini.
        - Jika ada file 'icon.ico' di sebelah .py / .exe (atau ter-bundle di dalam EXE), pakai itu (paling tajam di Windows).
        - Kalau tidak ada, fallback ke logo PNG yang sudah ter-embed di kode (LOGO_B64),
          jadi tetap jalan tanpa perlu file tambahan.
        """
        try:
            ico_path = BUNDLE_DIR / "icon.ico"
            if ico_path.exists():
                self.iconbitmap(str(ico_path))
                return
        except Exception:
            pass
        try:
            import base64 as _b64, io as _io
            from PIL import Image as _PILImage, ImageTk as _ImageTk
            _icon_data = _b64.b64decode(LOGO_B64)
            _icon_img = _PILImage.open(_io.BytesIO(_icon_data))
            self._app_icon_photo = _ImageTk.PhotoImage(_icon_img)
            self.iconphoto(True, self._app_icon_photo)
        except Exception:
            pass

    # ── Dark / Light mode ────────────────────────────────────────────────────
    def _theme_btn_text(self):
        return "🌙  Dark Mode" if self.cfg.get("theme", "light") == "light" else "☀️  Light Mode"

    def _toggle_theme(self):
        new_mode = "dark" if self.cfg.get("theme", "light") == "light" else "light"
        self._apply_theme_live(new_mode)

    def _apply_theme_live(self, mode):
        """Ganti tema secara langsung tanpa membangun ulang UI (data/isian user
        tidak hilang). Cara kerja: ganti konstanta warna global, lalu sapu
        seluruh widget yang sudah ada dan timpa warna lama -> warna baru."""
        if mode not in THEMES:
            return
        old_vals = {k: globals()[k] for k in _THEME_KEYS}
        _set_theme_globals(mode)
        new_vals = {k: globals()[k] for k in _THEME_KEYS}

        remap = {}
        for k, old_v in old_vals.items():
            new_v = new_vals[k]
            if old_v.lower() != new_v.lower():
                remap.setdefault(old_v.lower(), new_v)

        setup_style()  # refresh semua ttk widget (Notebook, Progressbar, Scrollbar, Combobox)
        self.configure(bg=BG)
        if remap:
            self._recolor_widget_tree(self, remap)

        self.cfg["theme"] = mode
        self._save_cfg()
        if hasattr(self, "_theme_btn"):
            self._theme_btn.configure(text=self._theme_btn_text())

    def _recolor_widget_tree(self, widget, remap):
        opts = ("bg", "fg", "background", "foreground", "activebackground",
                "activeforeground", "disabledforeground", "insertbackground",
                "highlightbackground", "highlightcolor", "selectbackground",
                "selectforeground", "troughcolor", "selectcolor", "readonlybackground")
        new_bg = None
        for opt in opts:
            try:
                cur = widget.cget(opt)
            except Exception:
                continue
            if not cur:
                continue
            new_v = remap.get(str(cur).lower())
            if new_v:
                try:
                    widget.configure(**{opt: new_v})
                    if opt == "bg":
                        new_bg = new_v
                except Exception:
                    pass
        # Refresh warna hover tombol (activebackground) supaya konsisten dgn bg baru
        if new_bg and isinstance(widget, tk.Button):
            try:
                widget.configure(activebackground=_darken(new_bg))
            except Exception:
                pass
        try:
            children = widget.winfo_children()
        except Exception:
            children = []
        for child in children:
            self._recolor_widget_tree(child, remap)

