    def _notify_done(self, out_path, start_time, log_widget=None):
        op = Path(out_path)
        sz_bytes = op.stat().st_size if op.exists() else 0
        elapsed = time.time() - start_time

        if sz_bytes >= 1024**3:
            sz_str = f"{sz_bytes/1024**3:.2f} GB"
        elif sz_bytes >= 1024**2:
            sz_str = f"{sz_bytes/1024**2:.1f} MB"
        else:
            sz_str = f"{sz_bytes/1024:.1f} KB"

        e_h = int(elapsed // 3600)
        e_m = int((elapsed % 3600) // 60)
        e_s = int(elapsed % 60)
        if e_h > 0:
            dur_str = f"{e_h} jam {e_m} menit {e_s} detik"
        elif e_m > 0:
            dur_str = f"{e_m} menit {e_s} detik"
        else:
            dur_str = f"{e_s:.1f} detik" if e_s < 10 else f"{e_s} detik"

        if log_widget:
            logw(log_widget, f"✅ Selesai! | {sz_str} | {dur_str}\n📁 {out_path}")

        def show():
            win = tk.Toplevel(self)
            win.title("✅ Render Selesai")
            win.configure(bg=BG)
            win.attributes("-alpha", 0.97)
            win.resizable(False, False)
            win.grab_set()

            tk.Frame(win, bg=ACCENT, height=4).pack(fill="x")
            tk.Label(win,
                     text="✅",
                     font=(FONT_FAMILY, 32, "bold"),
                     bg=SURFACE,
                     fg=SUCCESS).pack(pady=(18, 2))
            tk.Label(win,
                     text="RENDER SELESAI!",
                     font=(FONT_FAMILY, 14, "bold"),
                     bg=SURFACE,
                     fg=TEXT).pack()

            Sep(win).pack(fill="x", padx=20, pady=12)

            info = tk.Frame(win, bg=SURFACE)
            info.pack(fill="x", padx=24, pady=4)
            rows = [
                ("📄  Nama File", op.name, TEXT),
                ("💾  Ukuran File", sz_str, WARN),
                ("📁  Lokasi", str(op.parent), MUTED),
                ("⏱️   Durasi Render", dur_str, ACCENT),
            ]
            for i, (lbl, val, vc) in enumerate(rows):
                tk.Label(info,
                         text=lbl + "  :",
                         font=(FONT_FAMILY, 10, "bold"),
                         bg=SURFACE,
                         fg=MUTED,
                         width=18,
                         anchor="w").grid(row=i, column=0, sticky="w", pady=4)
                tk.Label(info,
                         text=val,
                         font=(FONT_FAMILY, 10),
                         bg=SURFACE,
                         fg=vc,
                         anchor="w",
                         wraplength=320).grid(row=i, column=1, sticky="w", pady=4, padx=8)

            Sep(win).pack(fill="x", padx=20, pady=12)

            btn_row = tk.Frame(win, bg=SURFACE)
            btn_row.pack(pady=(0, 16), padx=20, fill="x")
            BtnAccent(btn_row, "📁  Buka Folder",
                      lambda: reveal_in_folder(Path(out_path))).pack(side="left",
                                                                 expand=True,
                                                                 fill="x",
                                                                 padx=(0, 6))
            BtnOK(btn_row, "▶  Putar File",
                  lambda: open_file(out_path)).pack(side="left",
                                                      expand=True,
                                                      fill="x",
                                                      padx=(0, 6))
            Btn(btn_row, "✕  Tutup", win.destroy).pack(side="left", expand=True, fill="x")

            win.update_idletasks()
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            w = win.winfo_width()
            h = win.winfo_height()
            win.geometry(f"{w}x{h}+{(sw-w)//2}+{(sh-h)//2}")

        self.after(0, show)

