    # ── METADATA HELPER ───────────────────────────────────────────────────────
    def _add_metadata_to_cmd(self, cmd, title=None):
        if title is None:
            title = self.metadata.get("title", "CREATUBE STUDIO Output")

        cmd.extend(["-map_metadata", "0"])

        meta = {
            "title": title,
            "encoder": "CREATUBE STUDIO v2.8",
            "software": "CREATUBE STUDIO",
            "encoded_by": "CREATUBE STUDIO — KelasYoutubeBarengMasTian.com",
            "author": self.metadata.get("author", "KelasYoutubeBarengMasTian"),
            "publisher": self.metadata.get("publisher", "CREATUBE STUDIO"),
            "copyright": self.metadata.get("copyright", "© 2026 KelasYoutubeBarengMasTian.com"),
            "comment": self.metadata.get("comment", "Created with CREATUBE STUDIO"),
            "creation_time": time.strftime("%Y-%m-%dT%H:%M:%S"),
        }

        for k, v in meta.items():
            cmd.extend(["-metadata", f"{k}={v}"])

        cmd.extend(["-metadata:s:v:0", f"title={title}"])
        cmd.extend(["-metadata:s:a:0", "title=Audio Mix"])

        if str(cmd[-1]).lower().endswith((".mp4", ".m4v", ".mov")):
            cmd.extend(["-movflags", "+faststart"])

        return cmd

    def _load_metadata(self):
        cfg_path = APP_DIR / "settings.json"
        if cfg_path.exists():
            try:
                with open(cfg_path, encoding="utf-8") as f:
                    data = json.load(f)
                    if "metadata" in data:
                        self.metadata.update(data["metadata"])
            except:
                pass

    def _save_metadata(self):
        cfg_path = APP_DIR / "settings.json"
        try:
            data = self.cfg.copy()
            data["metadata"] = self.metadata
            with open(cfg_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
        except:
            pass

    def _save_user_metadata(self):
        if hasattr(self, '_meta_entries'):
            for key, entry in self._meta_entries.items():
                self.metadata[key] = entry.get().strip() or self.metadata.get(key, "")
        self._save_metadata()
        messagebox.showinfo("Metadata", "✅ Metadata berhasil disimpan!")

    def _save_user_metadata_loop(self):
        if hasattr(self, '_meta_entries_loop'):
            for key, entry in self._meta_entries_loop.items():
                self.metadata[key] = entry.get().strip() or self.metadata.get(key, "")
        self._save_metadata()
        messagebox.showinfo("Metadata", "✅ Metadata Single Loop berhasil disimpan!")

