    # TAB 1 — SINGLE LOOP
    # ════════════════════════════════════════════════════════════════
    def _tab_loop(self, p):
        self._loop_file = ""
        self._loop_src_dur = 0.0

        outer = tk.Frame(p, bg=BG)
