    def _loop_dur_changed(self):
        if not self._loop_src_dur:
            return
        try:
            mins = float(self._loop_dur.get())
            target_s = mins * 60
            loops = max(1, round(target_s / self._loop_src_dur))
            self._loop_times.delete(0, "end")
            self._loop_times.insert(0, str(loops))
            self._loop_update_info(target_s, loops)
        except (ValueError, ZeroDivisionError):
            pass

    def _loop_times_changed(self):
        if not self._loop_src_dur:
            return
        try:
            times = int(self._loop_times.get())
            target_s = self._loop_src_dur * times
            mins = target_s / 60
            self._loop_dur.delete(0, "end")
            self._loop_dur.insert(0, f"{mins:.1f}")
            self._loop_update_info(target_s, times)
        except (ValueError, ZeroDivisionError):
            pass

    def _loop_update_info(self, target_s, loops):
        src_dur = self._loop_src_dur
        src_str = f"{secs_to_ts(src_dur)}  ({src_dur/60:.1f} menit)"
        out_str = f"{secs_to_ts(target_s)}  ({target_s/60:.1f} menit)"
        src_size_mb = Path(self._loop_file).stat().st_size / (1024 * 1024) if self._loop_file else 0
        ratio = target_s / src_dur if src_dur else 1
        est_mb = src_size_mb * ratio
        if est_mb > 1024:
            size_str = f"~{est_mb/1024:.1f} GB"
        else:
            size_str = f"~{est_mb:.0f} MB"

        self._info_dur.config(text=src_str)
        self._info_loops.config(text=f"{loops}× pengulangan")
        self._info_out.config(text=out_str)
        self._info_size.config(text=size_str)

    def _loop_preview_file(self):
        if not self._loop_file:
            messagebox.showinfo("Preview", "Pilih file video terlebih dahulu.")
            return
        self._mg_video_preview_file(self._loop_file)

    def _loop_remove_file(self):
        if not self._loop_file:
            return
        if not messagebox.askyesno("Hapus File", "Hapus file video yang dipilih?"):
            return
        self._loop_file = ""
        self._loop_src_dur = 0.0
        self._loop_lbl.config(text="Belum ada file dipilih", fg=MUTED)
        self._loop_preview.config(text="Pilih video\nuntuk preview", fg=MUTED)
        self._loop_dur.delete(0, "end")
        self._loop_times.delete(0, "end")
        self._info_dur.config(text="—", fg=ACCENT)
        self._info_loops.config(text="—", fg=PURPLE)
        self._info_out.config(text="—", fg=SUCCESS)
        self._info_size.config(text="—", fg=WARN)
        self._loop_remove_btn.pack_forget()
        self._loop_preview_btn.pack_forget()
        logw(self._loop_log, "🗑 File video dihapus dari pilihan")

    def _loop_pick(self):
        f = filedialog.askopenfilename(title="Pilih Video",
                                       filetypes=[("Video", "*.mp4 *.mkv *.avi *.mov *.webm *.flv"),
                                                  ("All", "*.*")])
        if not f:
            return
        self._loop_file = f
        self._loop_lbl.config(text=Path(f).name, fg=TEXT)
        self._loop_remove_btn.pack(side="right", padx=(0, 6))
        self._loop_preview_btn.pack(side="right", padx=(0, 6))
        logw(self._loop_log, f"📂 File: {Path(f).name}")
        logw(self._loop_log, "⏳ Membaca info video...")
        self.update_idletasks()

        def read_info():
            ff = self._get_ff()
            dur = get_duration_ffmpeg(ff, f) if ff else 0.0
            size = Path(f).stat().st_size
            size_mb = size / (1024 * 1024)
            if size_mb > 1024:
                size_str = f"{size_mb/1024:.2f} GB"
            else:
                size_str = f"{size_mb:.1f} MB"

            def update():
                if dur > 0:
                    self._loop_src_dur = dur
                    default_target = 60 * 60
                    loops = max(1, round(default_target / dur))
                    actual_target = dur * loops
                    self._loop_dur.delete(0, "end")
                    self._loop_dur.insert(0, f"{actual_target/60:.1f}")
                    self._loop_times.delete(0, "end")
                    self._loop_times.insert(0, str(loops))
                    self._loop_update_info(actual_target, loops)
                    logw(
                        self._loop_log,
                        f"✅ Durasi: {secs_to_ts(dur)} ({dur/60:.1f} menit) | Ukuran: {size_str}")
                    self._loop_preview.config(
                        text=f"📹 {Path(f).name[:24]}\n"
                        f"⏱  {secs_to_ts(dur)} ({dur/60:.1f} min)\n"
                        f"💾 {size_str}\n\n"
                        f"🔁 Akan di-loop {loops}× →\n"
                        f"   {secs_to_ts(actual_target)} output",
                        fg=TEXT)
                else:
                    logw(self._loop_log, "⚠️  Durasi tidak terbaca, cek FFmpeg di Settings")
                    self._loop_preview.config(text=f"📹 {Path(f).name[:24]}\n⚠️  Durasi tidak terbaca",
                                              fg=WARN)

            self.after(0, update)

        threading.Thread(target=read_info, daemon=True).start()

    def _loop_render(self):
        ff = self._get_ff()
        if not ff:
            self._ff_err()
            return
        if not self._loop_file:
            messagebox.showwarning("Warning", "Pilih file video terlebih dahulu!")
            return
        try:
            mins = float(self._loop_dur.get())
        except:
            messagebox.showerror("Error", "Durasi harus angka!")
            return
        if mins <= 0:
            messagebox.showerror("Error", "Durasi harus lebih dari 0!")
            return

        out_name = self._loop_out.get().strip() or "output_loop"
        out_path = self._outpath(out_name)
        target_s = mins * 60

        src_dur = self._loop_src_dur
        if src_dur <= 0:
            logw(self._loop_log, "⏳ Membaca durasi video...")
            self._setstatus("⏳ Membaca durasi...", WARN)
            self.update_idletasks()
            src_dur = get_duration_ffmpeg(ff, self._loop_file)
        if src_dur <= 0:
            src_dur = 180.0
            logw(self._loop_log, "⚠️  Durasi tidak terbaca, pakai estimasi.")

        loops = max(int(target_s / src_dur) + 3, 5)
        try:
            times_disp = int(self._loop_times.get())
        except:
            times_disp = loops
        logw(self._loop_log,
             f"📊 Sumber: {secs_to_ts(src_dur)} | Loop: {times_disp}× | Target: {mins:.1f} menit")

        list_f = _tmp_path("_loop_list.txt")
        safe_path = Path(self._loop_file).as_posix()
        with open(list_f, "w", encoding="utf-8") as fh:
            for _ in range(loops):
                fh.write(f"file '{safe_path}'\n")

        cmd = [
            ff, "-y", "-f", "concat", "-safe", "0", "-i", list_f, "-t",
            str(target_s), "-c", "copy", out_path
        ]

        title_loop = self._loop_out.get().strip() or self.metadata.get("title", "Looped Video")
        cmd = self._add_metadata_to_cmd(cmd, title=title_loop)

        self._setstatus("⏳ Rendering loop...", WARN)
        logw(self._loop_log, "🚀 Render dimulai...")
        self._loop_pb["value"] = 0
        _loop_t0 = time.time()

        def on_p(v):
            self._loop_pb["value"] = v * 100
            self._setprog(v)

        def on_d(ok, c):
            if ok:
                op = Path(out_path)
                if op.exists() and op.stat().st_size > 1024:
                    self._setstatus("✅ Loop selesai!", SUCCESS)
                    self._loop_pb["value"] = 100
                    self._notify_done(out_path, _loop_t0, self._loop_log)
                else:
                    logw(self._loop_log, "❌ Output kosong/tidak ada! Cek format video.")
                    self._setstatus("❌ Output kosong", DANGER)
            else:
                logw(self._loop_log, f"❌ Gagal (code: {c})\nCek format video.")
                self._setstatus("❌ Render gagal", DANGER)

        run_ffmpeg_bg(cmd, on_p, on_d, total_duration=target_s)

