        name_lbl = Lbl(row, f"🎬 {Path(f).name[:40]}", fg=ACCENT, bg=SURF2, anchor="w", font=(FONT_FAMILY, 11, "bold"))
        name_lbl.pack(side="left", padx=8, pady=5, fill="x", expand=True)

        self._mg_video_files.append(f)
        d = {"path": f, "row": row}
        self._mg_video_rows.append(d)

        def _select(e=None):
            try:
                idx = self._mg_video_rows.index(d)
                self._mg_video_select(idx)
            except:
                pass

        row.bind("<Button-1>", _select)
        name_lbl.bind("<Button-1>", _select)

        def _remove():
            row.destroy()
            if d in self._mg_video_rows:
                self._mg_video_rows.remove(d)
            if d["path"] in self._mg_video_files:
                self._mg_video_files.remove(d["path"])
            if self._mg_video_sel_idx is not None:
                if self._mg_video_sel_idx >= len(self._mg_video_rows):
                    self._mg_video_sel_idx = None
            self._mg_video_repack()
            if not self._mg_video_rows:
                Lbl(parent,
                    "Belum ada video. Klik '+ Tambah Video'",
                    fg=MUTED,
                    bg=SURFACE,
                    font=FN).pack(pady=10)

        BtnDanger(row, "✕", _remove).pack(side="right", padx=6)

        def _preview():
            self._mg_video_preview_file(d["path"])

        BtnTeal(row, "▶", _preview, font=(FONT_FAMILY, 9), padx=6, pady=2).pack(side="right", padx=2)

