    def _mg_update_audio_total(self):
        if not self._mg_audio_rows:
            self._mg_audio_total_lbl.config(text="")
            return
        self._mg_audio_total_lbl.config(text="⏳ menghitung...", fg=MUTED)
        rows_snap = list(self._mg_audio_rows)

        def calc():
            ff = self._get_ff()
            if not ff:
                self.after(0, lambda: self._mg_audio_total_lbl.config(text=""))
                return
            total = sum(get_duration_ffmpeg(ff, r["path"]) for r in rows_snap)
            h = int(total // 3600)
            m = int((total % 3600) // 60)
            s = int(total % 60)
            txt = f"Total: {h}j {m}m {s}d  ({len(rows_snap)} lagu)" if h > 0 else f"Total: {m}m {s}d  ({len(rows_snap)} lagu)"
            self.after(0, lambda: self._mg_audio_total_lbl.config(text=txt, fg=SUCCESS))

        threading.Thread(target=calc, daemon=True).start()

    def _mg_make_audio_row(self, f, init_vol=100.0):
        parent = self._mg_audio_frame
        for w in parent.winfo_children():
            if isinstance(w, tk.Label) and "Belum" in w.cget("text"):
                w.destroy()
        vol_v = tk.DoubleVar(value=init_vol)
        row = tk.Frame(parent, bg=SURF2, highlightthickness=1, highlightbackground=SURF2, highlightcolor=SURF2)
        row.pack(fill="x", padx=4, pady=2)

        dur_lbl = Lbl(row, "...", fg=MUTED, bg=SURF2, width=10, anchor="e", font=(FONT_FAMILY, 9))

        def _load_dur():
            ff = self._get_ff()
            if not ff:
                return
            dur = get_duration_ffmpeg(ff, f)
            if dur > 0:
                m2, s2 = int(dur // 60), int(dur % 60)
                self.after(0, lambda: dur_lbl.config(text=f"{m2}:{s2:02d}", fg=ACCENT))

        threading.Thread(target=_load_dur, daemon=True).start()

        name_lbl = Lbl(row, f"🎵 {Path(f).name[:30]}", fg=TEAL, bg=SURF2, width=33, anchor="w", font=(FONT_FAMILY, 11, "bold"))
        name_lbl.pack(side="left", padx=8, pady=5)

        vol_lbl = Lbl(row, f"{int(init_vol)}%", fg=ACCENT, bg=SURF2, width=5)
        sc = Scale(row,
                   from_=0,
                   to=200,
                   orient="horizontal",
                   variable=vol_v,
                   length=160,
                   showvalue=False,
                   bg=SURF2)
        sc.config(command=lambda v: vol_lbl.config(text=f"{int(float(v))}%"))
        sc.pack(side="left")
        vol_lbl.pack(side="left")
        dur_lbl.pack(side="left", padx=4)

        d = {"path": f, "vol": vol_v, "row": row}
        self._mg_audio_rows.append(d)

        def _select(e=None):
            try:
                idx = self._mg_audio_rows.index(d)
                self._mg_audio_select(idx)
            except:
                pass

        row.bind("<Button-1>", _select)
        name_lbl.bind("<Button-1>", _select)
        dur_lbl.bind("<Button-1>", _select)
        vol_lbl.bind("<Button-1>", _select)

        def _remove():
            row.destroy()
            if d in self._mg_audio_rows:
                self._mg_audio_rows.remove(d)
            if self._mg_audio_sel_idx is not None:
                if self._mg_audio_sel_idx >= len(self._mg_audio_rows):
                    self._mg_audio_sel_idx = None
            self._mg_update_audio_total()

        BtnDanger(row, "✕", _remove).pack(side="right", padx=6)

        def _preview():
            self._mg_audio_preview_file(d["path"])

        BtnTeal(row, "▶", _preview, font=(FONT_FAMILY, 9), padx=6, pady=2).pack(side="right", padx=2)

        self._mg_update_audio_total()

