    def _mg_calc_duration(self, ff):
        dur_mode = self._mg_dur_mode.get()
        if dur_mode == "manual":
            try:
                h = int(self._mg_h.get() or 0)
                m = int(self._mg_m.get() or 0)
                s = int(self._mg_s.get() or 0)
                total = h * 3600 + m * 60 + s
            except:
                total = 0
            return max(total, 1.0)

        if not self._mg_audio_rows:
            if self._mg_video_files:
                dur = get_duration_ffmpeg(ff, self._mg_video_files[0])
                return max(dur, 1.0)
            return 3600.0

        total_audio = sum(get_duration_ffmpeg(ff, a["path"]) for a in self._mg_audio_rows)
        if dur_mode == "auto":
            return max(total_audio, 1.0)
        else:
            try:
                n = max(int(self._mg_multi_n.get()), 1)
            except:
                n = 1
            return max(total_audio * n, 1.0)

    def _mg_video_has_audio(self, ff, path):
        try:
            flags = 0x08000000 if sys.platform == "win32" else 0
            r = subprocess.run([ff, "-i", path],
                               capture_output=True,
                               text=True,
                               timeout=8,
                               creationflags=flags)
            return "Audio:" in r.stderr
        except:
            return False

    def _mg_build_cmd(self, ff, out_path, target_s):
        mute_v = self._mg_mute_video.get()

        has_video = bool(self._mg_video_files)
        has_music = bool(self._mg_audio_rows)
        has_fx = bool(self._mg_fx_rows)

        inputs = []
        idx = 0
        v_in = None
        m_in = None

        # ─── VIDEO INPUT (PERBAIKAN: loop terbatas) ─────────────────
        if has_video:
            if len(self._mg_video_files) == 1:
                video_dur = get_duration_ffmpeg(ff, self._mg_video_files[0])
                if video_dur > 0:
                    loop_count = max(1, int(target_s / video_dur) + 2)
                else:
                    loop_count = 999
                inputs += ["-stream_loop", str(loop_count), "-i", self._mg_video_files[0]]
                v_in = idx
                idx += 1
                logw(self._mlog, f"🔄 Video akan di-loop {loop_count}× (durasi: {video_dur:.1f}s)")
            else:
                vlist = _tmp_path("_mg_vlist.txt")
                total_video_dur = sum(get_duration_ffmpeg(ff, v) for v in self._mg_video_files)
                if total_video_dur > 0:
                    loop_count = max(1, int(target_s / total_video_dur) + 2)
                else:
                    loop_count = 999
                with open(vlist, "w", encoding="utf-8") as fh:
                    for _ in range(loop_count):
                        for v in self._mg_video_files:
                            fh.write(f"file '{Path(v).as_posix()}'\n")
                inputs += ["-f", "concat", "-safe", "0", "-i", vlist]
                v_in = idx
                idx += 1
                logw(self._mlog, f"🔄 {len(self._mg_video_files)} video di-loop {loop_count}× (total durasi: {total_video_dur:.1f}s)")

        # ─── AUDIO INPUT ─────────────────────────────────────────────────────
        if has_music:
            alist = _tmp_path("_mg_alist.txt")
            music_total = sum(get_duration_ffmpeg(ff, a["path"]) for a in self._mg_audio_rows)
            repeats = max(int(target_s / max(music_total, 0.1)) + 3, 2)

            with open(alist, "w", encoding="utf-8") as fh:
                for _ in range(repeats):
                    for a in self._mg_audio_rows:
                        fh.write(f"file '{Path(a['path']).as_posix()}'\n")

            inputs += ["-f", "concat", "-safe", "0", "-i", alist]
            m_in = idx
            idx += 1

        # ─── FX INPUT ────────────────────────────────────────────────────────
        fx_ins = []
        for fxd in self._mg_fx_rows:
            fx_dur = get_duration_ffmpeg(ff, fxd["path"])
            if fx_dur > 0:
                fx_loop = max(1, int(target_s / fx_dur) + 2)
            else:
                fx_loop = 999
            inputs += ["-stream_loop", str(fx_loop), "-i", fxd["path"]]
            fx_ins.append(idx)
            idx += 1

        # ─── FILTER COMPLEX ──────────────────────────────────────────────────
        fc = []
        audio_labels = []
        video_map_lbl = None

        vid_has_audio = has_video and not mute_v and self._mg_video_has_audio(
            ff, self._mg_video_files[0]) if has_video else False

        if has_video:
            video_map_lbl = f"{v_in}:v"

        if vid_has_audio:
            fc.append(f"[{v_in}:a]asetpts=PTS-STARTPTS[va]")
            audio_labels.append("[va]")

        if has_music:
            avg_vol = sum(a["vol"].get() / 100.0 for a in self._mg_audio_rows) / len(
                self._mg_audio_rows) if self._mg_audio_rows else 1.0
            fc.append(f"[{m_in}:a]volume={avg_vol:.3f},atrim=duration={target_s:.3f},asetpts=PTS-STARTPTS[amusic]")
            audio_labels.append("[amusic]")

        for i, fi in enumerate(fx_ins):
            vol = self._mg_fx_rows[i]["vol"].get() / 100.0
            fc.append(f"[{fi}:a]volume={vol:.3f},atrim=duration={target_s:.3f},asetpts=PTS-STARTPTS[afx{i}]")
            audio_labels.append(f"[afx{i}]")

        if audio_labels:
            if len(audio_labels) == 1:
                audio_map_lbl = audio_labels[0]
            else:
                fc.append("".join(audio_labels) +
                          f"amix=inputs={len(audio_labels)}:duration=longest:dropout_transition=0[aout]")
                audio_map_lbl = "[aout]"
        else:
            audio_map_lbl = None

        cmd = [ff, "-y"] + inputs
        if fc:
            cmd += ["-filter_complex", ";".join(fc)]

        if has_video and video_map_lbl:
            cmd += ["-map", video_map_lbl]
        if audio_map_lbl:
            cmd += ["-map", audio_map_lbl]
        else:
            cmd += ["-an"]

        cmd += ["-c:v", "copy"]

        if audio_map_lbl:
            cmd += ["-c:a", "aac", "-b:a", "192k", "-ar", "44100", "-ac", "2"]

        cmd += ["-t", f"{target_s:.2f}"]

        title = self._mo.get().strip() or Path(out_path).stem.replace("_", " ").title()
        cmd = self._add_metadata_to_cmd(cmd, title=title)

        cmd.append(out_path)

        return cmd

    def _mg_preview(self):
        ff = self._get_ff()
        if not ff:
            self._ff_err()
            return
        if not self._mg_video_files and not self._mg_audio_rows:
            messagebox.showwarning("Warning", "Tambahkan minimal 1 video atau audio!")
            return

        prev_path = _tmp_path("_preview_10s.mp4")
        logw(self._mlog, "▶  Rendering preview 10 detik...")
        self._setstatus("⏳ Preview rendering...", WARN)

        def do_preview():
            cmd = self._mg_build_cmd(ff, prev_path, target_s=10.0)

            def on_done(ok, c):
                if ok and Path(prev_path).exists() and Path(prev_path).stat().st_size > 1024:
                    logw(self._mlog, "✅ Preview siap!")
                    self._setstatus("✅ Preview siap!", SUCCESS)
                    try:
                        ffplay = _ff_sibling(ff, "ffplay")
                        subprocess.Popen([
                            ffplay, "-autoexit", "-window_title", "Preview 10s", "-x", "960", "-y", "540",
                            prev_path
                        ])
                    except:
                        open_file(prev_path)
                else:
                    logw(self._mlog, "❌ Preview gagal!")
                    self._setstatus("❌ Preview gagal", DANGER)

            run_ffmpeg_bg(cmd, None, on_done)

        threading.Thread(target=do_preview, daemon=True).start()

    def _mg_render(self):
        ff = self._get_ff()
        if not ff:
            self._ff_err()
            return
        if not self._mg_video_files and not self._mg_audio_rows:
            messagebox.showwarning("Warning", "Tambahkan minimal 1 video atau audio!")
            return

        out_path = self._outpath(self._mo.get().strip() or "merged_output")

        logw(self._mlog, "⏳ Menghitung durasi output...")
        self._setstatus("⏳ Menghitung durasi...", WARN)
        self.update_idletasks()

        def do_render():
            target_s = self._mg_calc_duration(ff)
            logw(self._mlog, f"⚙️  Target: {secs_to_ts(target_s)} | Mode: Copy Stream")

            cmd = self._mg_build_cmd(ff, out_path, target_s)
            logw(self._mlog, "🚀 Render dimulai...")
            self._mpb["value"] = 0
            self._setstatus("⏳ Rendering...", WARN)
            _mg_t0 = time.time()

            def on_p(v):
                self._mpb["value"] = v * 100
                self._setprog(v)

            def on_d(ok, c):
                if ok:
                    op = Path(out_path)
                    if op.exists() and op.stat().st_size > 1024:
                        self._setstatus("✅ Merger selesai!", SUCCESS)
                        self._mpb["value"] = 100
                        if self._mts.get():
                            self._mg_gen_ts(ff)
                        self._notify_done(out_path, _mg_t0, self._mlog)
                    else:
                        logw(self._mlog, "❌ Output file kosong")
                        self._setstatus("❌ Output kosong", DANGER)
                else:
                    logw(self._mlog, f"❌ Render gagal!")
                    self._setstatus("❌ Render gagal", DANGER)

            run_ffmpeg_bg(cmd, on_p, on_d, total_duration=target_s)

        threading.Thread(target=do_render, daemon=True).start()

    def _mg_gen_ts(self, ff):
        if not self._mg_audio_rows:
            return
        lines = ["▶ TIMESTAMPS\n"]
        elapsed = 0.0
        for ar in self._mg_audio_rows:
            dur = get_duration_ffmpeg(ff, ar["path"])
            lines.append(f"{secs_to_ts(elapsed)} — {Path(ar['path']).stem}")
            elapsed += dur
        ts = str(Path(self.cfg["outdir"]) / "timestamps.txt")
        with open(ts, "w", encoding="utf-8") as fh:
            fh.write("\n".join(lines))
        logw(self._mlog, f"📋 Timestamps → {ts}")

