    def _get_metadata(self, filepath):
        """Ambil metadata dengan fallback ke filesystem."""
        if not Path(filepath).exists():
            return {"error": "File tidak ditemukan"}

        stat = Path(filepath).stat()
        basic = {
            "format": {
                "filename": Path(filepath).name,
                "size": str(stat.st_size),
                "format_name": Path(filepath).suffix.upper().replace(".", ""),
                "filesize_mb": f"{stat.st_size/1024/1024:.1f} MB"
            },
            "streams": []
        }

        ff = self._get_ff()
        if ff:
            ffprobe = None
            ffprobe = _ff_sibling(ff, "ffprobe")

            if ffprobe:
                try:
                    flags = 0x08000000 if sys.platform == "win32" else 0
                    cmd = [
                        ffprobe, "-v", "quiet", "-print_format", "json", "-show_format", "-show_streams",
                        filepath
                    ]
                    result = subprocess.run(cmd,
                                            capture_output=True,
                                            text=True,
                                            timeout=15,
                                            creationflags=flags)
                    if result.returncode == 0 and result.stdout.strip():
                        full = json.loads(result.stdout)
                        if "format" in full:
                            full["format"]["filesize_mb"] = basic["format"]["filesize_mb"]
                        return full
                except:
                    pass

        basic["note"] = "FFprobe tidak tersedia. Install FFmpeg untuk analisis lengkap."
        return basic

    def _pick_file(self, side):
        fp = filedialog.askopenfilename(title=f"Pilih File Panel {side}",
                                        filetypes=[("Media", "*.mp4 *.mkv *.avi *.mov *.mp3 *.wav *.m4a"),
                                                   ("All", "*.*")])
        if not fp:
            return

        if side == "A":
            self._inspector_file_a = fp
            self._lbl_a.config(text=Path(fp).name, fg=TEXT)
        else:
            self._inspector_file_b = fp
            self._lbl_b.config(text=Path(fp).name, fg=TEXT)

        logw(self._log, f"📂 [{side}] Memuat: {Path(fp).name}")

        frame = self._frame_a if side == "A" else self._frame_b
        for w in frame.winfo_children():
            w.destroy()
        Lbl(frame, "⏳ Membaca metadata...", fg=WARN, bg=SURFACE).pack(pady=20)
        self.update_idletasks()

        def load():
            meta = self._get_metadata(fp)
            if side == "A":
                self._inspector_meta_a = meta
            else:
                self._inspector_meta_b = meta
            self.after(0, lambda: self._display(side, meta))

        threading.Thread(target=load, daemon=True).start()

    def _display(self, side, meta):
        frame = self._frame_a if side == "A" else self._frame_b

        for w in frame.winfo_children():
            w.destroy()

        if "error" in meta:
            Lbl(frame, f"❌ {meta['error']}", fg=DANGER, bg=SURFACE).pack(pady=10)
            logw(self._log, f"❌ [{side}] {meta['error']}")
            return

        logw(self._log, f"✅ [{side}] Metadata berhasil dibaca")

        cv = tk.Canvas(frame, bg=SURFACE, highlightthickness=0)
        sb = tk.Scrollbar(frame, orient="vertical", command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        cv.pack(side="left", fill="both", expand=True)

        inner = tk.Frame(cv, bg=SURFACE)
        cv.create_window((0, 0), window=inner, anchor="nw")
        inner.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))

        fmt = meta.get("format", {})
        streams = meta.get("streams", [])
        tags = fmt.get("tags", {})

        # Basic Info
        tf = tk.Frame(inner, bg=SURF2)
        tf.pack(fill="x", padx=8, pady=6)
        tk.Label(tf, text="📊 INFORMASI DASAR", bg=SURF2, fg=GOLD, font=FNB).pack(anchor="w", padx=10, pady=(8, 4))

        items = [
            ("Nama File", fmt.get("filename", "N/A")[:40]),
            ("Ukuran", fmt.get("filesize_mb", "N/A")),
            ("Format", fmt.get("format_name", "N/A")),
        ]

        dur = float(fmt.get("duration", 0))
        if dur > 0:
            items.insert(2, ("Durasi", f"{secs_to_ts(dur)} ({dur/60:.1f} menit)"))

        br = int(fmt.get("bit_rate", 0)) // 1000
        if br > 0:
            items.append(("Bitrate", f"{br} kbps"))

        for label, value in items:
            row = tk.Frame(tf, bg=SURF2)
            row.pack(fill="x", padx=10, pady=2)
            Lbl(row, f"{label}:", fg=MUTED, bg=SURF2, width=14, anchor="w").pack(side="left")
            Lbl(row, str(value), fg=TEXT, bg=SURF2, font=FNB).pack(side="left")

        # Metadata Tags (HANYA HUMAN-FRIENDLY)
        exclude_keys = [
            "major_brand", "minor_version", "compatible_brands", "encoder",
            "handler_name", "vendor_id"
        ]

        filtered_tags = {k: v for k, v in tags.items() if k not in exclude_keys}

        if filtered_tags:
            tk.Frame(inner, bg=SURF3, height=1).pack(fill="x", padx=8, pady=8)

            tag_frame = tk.Frame(inner, bg=SURF2)
            tag_frame.pack(fill="x", padx=8, pady=(0, 6))

            tk.Label(tag_frame,
                     text="🏷️ METADATA TAGS (Author, Copyright, Title, dll)",
                     bg=SURF2,
                     fg=PURPLE,
                     font=FNB).pack(anchor="w", padx=10, pady=(8, 4))

            priority_keys = [
                "title", "artist", "author", "encoded_by", "copyright", 
                "comment", "publisher", "album", "genre", "date", "creation_time"
            ]

            displayed = set()
            for key in priority_keys:
                if key in filtered_tags:
                    value = filtered_tags[key]
                    row = tk.Frame(tag_frame, bg=SURFACE)
                    row.pack(fill="x", padx=10, pady=2)

                    label_color = ACCENT if key in ["title", "author", "encoded_by", "copyright"] else TEAL
                    Lbl(row,
                        f"{key}:",
                        fg=label_color,
                        bg=SURFACE,
                        width=16,
                        anchor="w",
                        font=(FONT_FAMILY, 9)).pack(side="left")

                    val_str = str(value)[:50] + "..." if len(str(value)) > 50 else str(value)
                    Lbl(row, val_str, fg=TEXT, bg=SURFACE, wraplength=250,
                        font=(FONT_FAMILY, 9)).pack(side="left", padx=(8, 0))
                    displayed.add(key)

            for key, value in filtered_tags.items():
                if key not in displayed:
                    row = tk.Frame(tag_frame, bg=SURFACE)
                    row.pack(fill="x", padx=10, pady=2)
                    Lbl(row, f"{key}:", fg=MUTED, bg=SURFACE, width=16, anchor="w").pack(side="left")
                    val_str = str(value)[:50] + "..." if len(str(value)) > 50 else str(value)
                    Lbl(row, val_str, fg=MUTED, bg=SURFACE, wraplength=250).pack(side="left", padx=(8, 0))

        # Streams
        if streams:
            tk.Frame(inner, bg=SURF3, height=1).pack(fill="x", padx=8, pady=8)
            sf = tk.Frame(inner, bg=SURF2)
            sf.pack(fill="x", padx=8, pady=(0, 6))
            tk.Label(sf, text="🎬 STREAMS (Codec & Teknis)", bg=SURF2, fg=GOLD,
                     font=FNB).pack(anchor="w", padx=10, pady=(8, 4))

            for i, s in enumerate(streams):
                ct = s.get("codec_type", "unknown")
                bgcol = SURFACE if i % 2 == 0 else SURF2
                srow = tk.Frame(sf, bg=bgcol)
                srow.pack(fill="x", padx=6, pady=2)

                icon = {"video": "🎥", "audio": "🎵"}.get(ct, "📄")
                tk.Label(srow, text=f"{icon} {ct.upper()}", bg=bgcol, fg=TEAL, font=FNB).pack(anchor="w",
                                                                                               padx=10,
                                                                                               pady=2)

                df = tk.Frame(srow, bg=bgcol)
                df.pack(fill="x", padx=20, pady=(0, 6))

                if ct == "video":
                    details = [
                        ("Codec", s.get("codec_name", "N/A")),
                        ("Resolusi", f"{s.get('width','?')}×{s.get('height','?')}"),
                        ("Frame Rate", s.get("r_frame_rate", "N/A")),
                        ("Pixel Format", s.get("pix_fmt", "N/A")),
                    ]
                    vbr = int(s.get("bit_rate", 0)) // 1000
                    if vbr > 0:
                        details.append(("Bitrate Video", f"{vbr} kbps"))
                elif ct == "audio":
                    details = [
                        ("Codec", s.get("codec_name", "N/A")),
                        ("Sample Rate", f"{s.get('sample_rate','N/A')} Hz"),
                        ("Channels", s.get("channels", "N/A")),
                        ("Channel Layout", s.get("channel_layout", "N/A")),
                    ]
                    abr = int(s.get("bit_rate", 0)) // 1000
                    if abr > 0:
                        details.append(("Bitrate Audio", f"{abr} kbps"))
                else:
                    details = [("Codec", s.get("codec_name", "N/A"))]

                for lbl, val in details:
                    r = tk.Frame(df, bg=bgcol)
                    r.pack(fill="x", pady=1)
                    Lbl(r, f"{lbl}:", fg=MUTED, bg=bgcol, width=16, anchor="w").pack(side="left")
                    Lbl(r, str(val), fg=TEXT, bg=bgcol).pack(side="left")

        if "note" in meta:
            tk.Frame(inner, bg=SURF3, height=1).pack(fill="x", padx=8, pady=8)
            Lbl(inner, f"ℹ️ {meta['note']}", fg=WARN, bg=SURFACE, font=(FONT_FAMILY, 9)).pack(pady=6)

    def _compare(self):
        if not self._inspector_file_a or not self._inspector_file_b:
            messagebox.showwarning("Warning", "Pilih kedua file terlebih dahulu!")
            return

        def extract(m):
            fmt = m.get("format", {})
            streams = m.get("streams", [])
            tags = fmt.get("tags", {})
            vid = next((s for s in streams if s.get("codec_type") == "video"), {})
            aud = next((s for s in streams if s.get("codec_type") == "audio"), {})

            dur = float(fmt.get("duration", 0))
            result = {
                "Ukuran": fmt.get("filesize_mb", "N/A"),
                "Durasi": secs_to_ts(dur) if dur > 0 else "N/A",
                "Video Codec": vid.get("codec_name", "N/A"),
                "Resolusi": f"{vid.get('width','?')}×{vid.get('height','?')}" if vid else "N/A",
                "Frame Rate": vid.get("r_frame_rate", "N/A") if vid else "N/A",
                "Audio Codec": aud.get("codec_name", "N/A"),
                "Sample Rate": f"{aud.get('sample_rate','N/A')} Hz" if aud else "N/A",
                "Author": tags.get("author", tags.get("artist", "N/A")),
                "Copyright": tags.get("copyright", "N/A"),
                "Encoded By": tags.get("encoded_by", "N/A"),
                "Title": tags.get("title", "N/A"),
            }
            return result

        va = extract(self._inspector_meta_a)
        vb = extract(self._inspector_meta_b)

        win = tk.Toplevel(self)
        win.title("Perbandingan Metadata")
        win.geometry("750x600")
        win.configure(bg=SURFACE)

        tk.Frame(win, bg=ACCENT, height=3).pack(fill="x")
        tk.Label(win, text="Perbandingan File", font=FH2, bg=SURFACE, fg=TEXT).pack(pady=12)

        info = tk.Frame(win, bg=SURF2)
        info.pack(fill="x", padx=16, pady=4)
        Lbl(info, f"🔵 A: {Path(self._inspector_file_a).name}", fg=ACCENT, bg=SURF2).pack(anchor="w",
                                                                                          padx=10,
                                                                                          pady=2)
        Lbl(info, f"🟢 B: {Path(self._inspector_file_b).name}", fg=TEAL, bg=SURF2).pack(anchor="w",
                                                                                        padx=10,
                                                                                        pady=2)

        hdr = tk.Frame(win, bg=SURF3)
        hdr.pack(fill="x", padx=16, pady=(12, 2))
        Lbl(hdr, "Properti", fg=GOLD, bg=SURF3, width=18, anchor="w", font=FNB).pack(side="left", padx=10)
        Lbl(hdr, "FILE A", fg=ACCENT, bg=SURF3, width=22, anchor="w", font=FNB).pack(side="left", padx=4)
        Lbl(hdr, "FILE B", fg=TEAL, bg=SURF3, width=22, anchor="w", font=FNB).pack(side="left", padx=4)

        for i, (k, v) in enumerate(va.items()):
            vb_val = vb.get(k, "N/A")
            bgcol = SURFACE if i % 2 == 0 else SURF2
            row = tk.Frame(win, bg=bgcol)
            row.pack(fill="x", padx=16, pady=1)

            Lbl(row, k, fg=MUTED, bg=bgcol, width=18, anchor="w").pack(side="left", padx=10)

            fg_a = TEXT if v == vb_val else WARN
            Lbl(row, str(v), fg=fg_a, bg=bgcol, width=22, anchor="w").pack(side="left", padx=4)

            fg_b = TEXT if v == vb_val else TEAL
            Lbl(row, str(vb_val), fg=fg_b, bg=bgcol, width=22, anchor="w").pack(side="left", padx=4)

        Btn(win, "Tutup", win.destroy).pack(pady=16)

    def _export(self):
        if not self._inspector_file_a and not self._inspector_file_b:
            messagebox.showwarning("Warning", "Tidak ada file untuk diexport!")
            return

        out = filedialog.asksaveasfilename(defaultextension=".txt", filetypes=[("Text", "*.txt")])
        if not out:
            return

        with open(out, "w", encoding="utf-8") as f:
            f.write(f"=== METADATA EXPORT ===\n{time.strftime('%Y-%m-%d %H:%M:%S')}\n\n")
            for side, fp, meta in [("A", self._inspector_file_a, self._inspector_meta_a),
                                   ("B", self._inspector_file_b, self._inspector_meta_b)]:
                if fp:
                    f.write(f"\n{'='*50}\nFILE {side}: {fp}\n{'='*50}\n")
                    f.write(json.dumps(meta, indent=2, ensure_ascii=False))

        logw(self._log, f"📄 Export: {out}")
        messagebox.showinfo("Sukses", f"Metadata disimpan di:\n{out}")

    def _clear(self):
        self._inspector_file_a = self._inspector_file_b = ""
        self._inspector_meta_a = self._inspector_meta_b = {}
        self._lbl_a.config(text="Belum ada file", fg=MUTED)
        self._lbl_b.config(text="Belum ada file", fg=MUTED)
        for frm in [self._frame_a, self._frame_b]:
            for w in frm.winfo_children():
                w.destroy()
            Lbl(frm, "Pilih file untuk melihat metadata", fg=MUTED, bg=SURFACE).pack(pady=20)
        logw(self._log, "🗑 Panel direset")

    # ════════════════════════════════════════════════════════════════
    # TAB PANDUAN & SETTINGS
    # ════════════════════════════════════════════════════════════════
    def _tab_panduan(self, p):
        Lbl(p, "Panduan Penggunaan CREATUBE STUDIO", font=FH1).pack(pady=20)
        Lbl(p, "1. Single Loop: Loop video hingga durasi target", fg=MUTED).pack(pady=2)
        Lbl(p, "2. AV Merger: Gabungkan video + audio + FX", fg=MUTED).pack(pady=2)
        Lbl(p, "3. Metadata Inspector: Analisis & bandingkan metadata", fg=MUTED).pack(pady=2)
        Lbl(p, "4. Settings: Atur lokasi FFmpeg dan output", fg=MUTED).pack(pady=2)

        if _IS_MAC:
            Lbl(p, "\n── Catatan untuk pengguna Mac ──", font=FH2).pack(pady=(16, 4))
            Lbl(p, "• Install FFmpeg via Terminal:  brew install ffmpeg",
                fg=MUTED).pack(pady=2)
            Lbl(p, "• File hasil render disimpan di folder Movies/CreaTubeStudio",
                fg=MUTED).pack(pady=2)
            Lbl(p, "• Settings disimpan di ~/Library/Application Support/CREATUBE STUDIO",
                fg=MUTED).pack(pady=2)
            Lbl(p, "• Tutup aplikasi dengan Cmd+Q, bukan hanya klik merah",
                fg=MUTED).pack(pady=2)

    def _tab_settings(self, p):
        Lbl(p, "Settings", font=FH1).pack(pady=20)

        ff_frame = tk.Frame(p, bg=BG)
        ff_frame.pack(fill="x", padx=20, pady=10)
        Lbl(ff_frame, "FFmpeg Path:", width=15).pack(side="left")
        self._ff_entry = Entry(ff_frame, width=50)
        self._ff_entry.insert(0, self.cfg.get("ffmpeg", ""))
        self._ff_entry.pack(side="left", padx=5)
        Btn(ff_frame, "🔍 Auto Detect", self._settings_detect_ffmpeg).pack(side="left", padx=5)

        out_frame = tk.Frame(p, bg=BG)
        out_frame.pack(fill="x", padx=20, pady=10)
        Lbl(out_frame, "Output Folder:", width=15).pack(side="left")
        self._out_entry = Entry(out_frame, width=50)
        self._out_entry.insert(0, self.cfg.get("outdir", ""))
        self._out_entry.pack(side="left", padx=5)
        Btn(out_frame, "📁 Browse", self._settings_browse_outdir).pack(side="left", padx=5)

        fmt_frame = tk.Frame(p, bg=BG)
        fmt_frame.pack(fill="x", padx=20, pady=10)
        Lbl(fmt_frame, "Format Output:", width=15).pack(side="left")
        self._fmt_var = tk.StringVar(value=self.cfg.get("fmt", "mp4"))
        fmt_combo = ttk.Combobox(fmt_frame,
                                 textvariable=self._fmt_var,
                                 values=["mp4", "mkv", "mov", "avi"],
                                 width=10)
        fmt_combo.pack(side="left", padx=5)

        BtnOK(p, "💾 Simpan Settings", self._settings_save, font=FNB, padx=20).pack(pady=20)

    def _settings_detect_ffmpeg(self):
        detected = find_ffmpeg()
        if detected:
            self._ff_entry.delete(0, tk.END)
            self._ff_entry.insert(0, detected)
            messagebox.showinfo("Sukses", f"FFmpeg ditemukan:\n{detected}")
        else:
            if _IS_MAC:
                ins = "brew install ffmpeg"
            elif _IS_WIN:
                ins = "winget install ffmpeg"
            else:
                ins = "sudo apt install ffmpeg"
            messagebox.showerror("Gagal",
                                 f"FFmpeg tidak ditemukan!\n\nInstall dengan perintah:\n{ins}")

    def _settings_browse_outdir(self):
        folder = filedialog.askdirectory(title="Pilih Folder Output")
        if folder:
            self._out_entry.delete(0, tk.END)
            self._out_entry.insert(0, folder)

    def _settings_save(self):
        self.cfg["ffmpeg"] = self._ff_entry.get().strip()
        self.cfg["outdir"] = self._out_entry.get().strip()
        self.cfg["fmt"] = self._fmt_var.get()
        self._save_cfg()
        self._update_ff_lbl()
        messagebox.showinfo("Settings", "✅ Settings berhasil disimpan!")

    def _load_cfg(self):
        cfg_path = APP_DIR / "settings.json"
        if cfg_path.exists():
            try:
                with open(cfg_path, encoding="utf-8") as f:
                    data = json.load(f)
                    for k in self.cfg:
                        if k in data:
                            self.cfg[k] = data[k]
                    if "metadata" in data:
                        self.metadata.update(data["metadata"])
            except:
                pass

    def _save_cfg(self):
        cfg_path = APP_DIR / "settings.json"
        try:
            data = self.cfg.copy()
            data["metadata"] = self.metadata
            with open(cfg_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
        except:
            pass


